#!/usr/bin/env python3"""乐采云平台 - 每日招标采购信息抓取数据源: https://www.lecaiyun.com/ (乐采寻源+项目采购)关注: 安防弱电智能化+警用装备类产品输出: 简化三分类报告（采购意向/招标公告/中标公告）方案: Selenium + Chrome CDP（乐采云为Vue SPA，需浏览器渲染）"""import jsonimport osimport reimport sysimport timeimport loggingfrom datetime import datetime, timedeltafrom pathlib import Pathfrom typing import Optional, Dict, List# ── Selenium/CDP ──────────────────────────────────────────from selenium import webdriverfrom selenium.webdriver.common.by import Byfrom selenium.webdriver.support.ui import WebDriverWaitfrom selenium.webdriver.support import expected_conditions as ECfrom selenium.webdriver.chrome.options import Optionsfrom selenium.common.exceptions import TimeoutException, NoSuchElementException# ── 配置 ──────────────────────────────────────────────────CHROME_DEBUG_PORT = 9222SOURCE_URLS = {    "采购意向公开": "https://sourcing-lcy.lecaiyun.com/luban/announcement?announcementType=1",    "招标公告": "https://sourcing-lcy.lecaiyun.com/luban/announcement?announcementType=2",    "中标公告": "https://sourcing-lcy.lecaiyun.com/luban/announcement?announcementType=3",}# 备用: 乐采寻源首页SOURCING_HOME = "https://sourcing-lcy.lecaiyun.com/luban/jingjia"# 脚本目录SCRIPT_DIR = Path(__file__).parentLOG_DIR = SCRIPT_DIR / "logs"STATE_FILE = SCRIPT_DIR / "lecaiyun_state.json"# ── Logging ────────────────────────────────────────────────LOG_DIR.mkdir(exist_ok=True)today_str = datetime.now().strftime("%Y-%m-%d")log_file = LOG_DIR / f"lecaiyun_{today_str}.log"logging.basicConfig(    level=logging.INFO,    format="%(asctime)s [%(levelname)s] %(message)s",    handlers=[        logging.FileHandler(log_file, encoding="utf-8"),        logging.StreamHandler(),    ],)log = logging.getLogger(__name__)# ── 浏览器连接 ────────────────────────────────────────────def get_driver():    """通过CDP连接到已运行的Chrome"""    options = Options()    options.add_experimental_option("debuggerAddress", f"127.0.0.1:{CHROME_DEBUG_PORT}")    options.add_argument("--disable-blink-features=AutomationControlled")    try:        driver = webdriver.Chrome(options=options)        log.info("成功连接到Chrome调试端口")        return driver    except Exception as e:        log.error(f"无法连接Chrome调试端口 {CHROME_DEBUG_PORT}: {e}")        log.error("请确保Chrome以调试模式运行:")        log.error(f"  /Applications/Google\\ Chrome.app/Contents/MacOS/Google\\ Chrome --remote-debugging-port={CHROME_DEBUG_PORT}")        raise# ── 数据抓取 ──────────────────────────────────────────────def scrape_page(driver, url: str, max_retries: int = 3) -> List[dict]:    """抓取页面中的招标公告列表"""    items = []    for attempt in range(max_retries):        try:            log.info(f"  正在访问: {url} (尝试 {attempt + 1}/{max_retries})")            driver.get(url)            # 等待页面加载完成            time.sleep(5)  # 给Vue SPA渲染时间            # 尝试等待公告列表加载            try:                WebDriverWait(driver, 15).until(                    lambda d: len(d.find_elements(By.CSS_SELECTOR, "a[href*='detail'], a[href*='announcement'], tr, .list-item, .bidding-item, .announcement-item, .notice-item")) > 0                    or len(d.page_source) > 50000  # 页面有足够内容                )            except TimeoutException:                log.warning("  等待超时，继续尝试提取数据")            # 尝试多种选择器提取公告信息            items = extract_from_dom(driver)            if items:                log.info(f"  成功提取 {len(items)} 条数据")                break            else:                log.warning(f"  未提取到数据，{2 if attempt < max_retries else 0}秒后重试...")                time.sleep(2)        except Exception as e:            log.error(f"  访问失败: {e}")            if attempt < max_retries - 1:                time.sleep(3)    return itemsdef extract_from_dom(driver) -> List[dict]:    """从DOM中提取公告列表数据"""    items = []    page_source = driver.page_source    # 策略1: 尝试提取 SSR 初始状态中的JSON数据    try:        match = re.search(r'window\.__INITIAL_STATE__\s*=\s*({.*?});', page_source, re.DOTALL)        if match:            state = json.loads(match.group(1))            log.info(f"  找到 SSR 初始状态数据")            # 递归搜索所有列表数据            items_from_state = extract_from_state(state)            if items_from_state:                return items_from_state    except Exception as e:        log.debug(f"  SSR数据提取失败: {e}")    # 策略2: 查找页面中所有可能的公告链接和标题    try:        # 查找包含"采购""招标""中标"等关键词的链接        links = driver.find_elements(By.CSS_SELECTOR,            "a[href*='detail'], a[href*='announcement'], a[href*='bidding'], a[href*='notice']")        for link in links:            try:                text = link.text.strip()                href = link.get_attribute("href")                if text and href and len(text) > 5:                    # 检查是否为公告标题                    if any(kw in text for kw in ['采购', '招标', '中标', '公告', '项目', '工程']):                        # 尝试获取父级元素中的额外信息                        parent = link.find_element(By.XPATH, "..")                        parent_text = parent.text.strip()                        items.append({                            "title": text,                            "url": href,                            "context": parent_text[:200],                        })            except:                continue    except Exception as e:        log.debug(f"  链接提取失败: {e}")    # 策略3: 查找表格行    if not items:        try:            rows = driver.find_elements(By.CSS_SELECTOR, "table tr, .list-row, .table-row")            for row in rows:                try:                    row_text = row.text.strip()                    if row_text and any(kw in row_text for kw in ['采购', '招标', '中标', '公告']):                        links_in_row = row.find_elements(By.TAG_NAME, "a")                        if links_in_row:                            items.append({                                "title": links_in_row[0].text.strip(),                                "url": links_in_row[0].get_attribute("href"),                                "context": row_text[:200],                            })                except:                    continue        except:            pass    return itemsdef extract_from_state(state, depth=0, max_depth=5) -> List[dict]:    """递归搜索SSR初始状态中的招标数据"""    if depth > max_depth:        return []    items = []    if isinstance(state, dict):        # 查找可能的列表字段        for key in ['data', 'list', 'items', 'records', 'rows', 'result', 'biddingList', 'announcementList']:            if key in state and isinstance(state[key], list):                for item in state[key]:                    if isinstance(item, dict):                        parsed = parse_state_item(item)                        if parsed:                            items.append(parsed)        # 递归搜索        for value in state.values():            if isinstance(value, (dict, list)):                items.extend(extract_from_state(value, depth + 1, max_depth))    elif isinstance(state, list):        for item in state[:50]:  # 限制搜索范围            if isinstance(item, (dict, list)):                items.extend(extract_from_state(item, depth + 1, max_depth))    return itemsdef parse_state_item(item: dict) -> Optional[dict]:    """解析SSR状态中的单个公告项"""    title = (item.get("title") or item.get("name") or             item.get("projectName") or item.get("announcementTitle") or "")    if not title or len(title) < 3:        return None    # 检查是否为招标相关    if not any(kw in title for kw in ['采购', '招标', '中标', '公告', '项目', '工程',                                       '服务', '货物', '施工', '监理', '设计']):        return None    # 提取URL    url = (item.get("url") or item.get("href") or item.get("link") or           item.get("detailUrl") or item.get("announcementUrl") or "")    # 提取预算    budget = (item.get("budget") or item.get("budgetPrice") or              item.get("budgetAmount") or item.get("预算金额") or "")    # 提取时间    pub_date = (item.get("publishDate") or item.get("createTime") or                item.get("publishTime") or item.get("发布时间") or "")    # 提取采购单位    purchaser = (item.get("purchaser") or item.get("purchaseName") or                 item.get("采购人") or item.get("采购单位") or "")    return {        "title": str(title),        "url": str(url) if url else "",        "budget": str(budget) if budget else "",        "publish_date": str(pub_date) if pub_date else "",        "purchaser": str(purchaser) if purchaser else "",    }def enrich_items(driver, items: List[dict]) -> List[dict]:    """点击详情链接获取更多信息"""    enriched = []    current_handle = driver.current_window_handle    for item in items:        try:            url = item.get("url", "")            if not url:                enriched.append(item)                continue            # 在新标签页打开详情            driver.execute_script(f"window.open('{url}', '_blank');")            driver.switch_to.window(driver.window_handles[-1])            time.sleep(2)            # 提取详情页信息            detail_text = driver.page_source            # 提取预算金额            budget_patterns = [                r'预算[金额价]*[：:]\s*([\d,]+\.?\d*)\s*万?元?',                r'采购预算[：:]\s*([\d,]+\.?\d*)',                r'最高限价[：:]\s*([\d,]+\.?\d*)',                r'项目预算[：:]\s*([\d,]+\.?\d*)',            ]            for pattern in budget_patterns:                match = re.search(pattern, detail_text)                if match:                    budget = match.group(1).replace(',', '')                    try:                        item["budget_amount"] = float(budget)                    except:                        item["budget_amount"] = budget                    break            # 提取时间            time_patterns = [                r'(投标截止|开标|报名截止|提交截止)[时间日期]*[：:]\s*(\d{4}[-/]\d{1,2}[-/]\d{1,2}[T\s]?\d{1,2}:\d{2})',                r'(公告发布|发布时间)[：:]\s*(\d{4}[-/]\d{1,2}[-/]\d{1,2})',            ]            for pattern in time_patterns:                match = re.search(pattern, detail_text)                if match:                    item["deadline"] = match.group(2)                    break            driver.close()            driver.switch_to.window(current_handle)            enriched.append(item)        except Exception as e:            log.debug(f"  详情提取失败 [{item.get('title', '')[:30]}]: {e}")            try:                if len(driver.window_handles) > 1:                    driver.close()                driver.switch_to.window(current_handle)            except:                pass            enriched.append(item)    return enriched# ── 报告格式化（简化三分类） ──────────────────────────────def format_simplified_report(all_items: Dict[str, List[dict]]) -> str:    """格式化简化三分类报告"""    lines = [f"📋 乐采云 - 招标采购每日汇总 ({today_str})", ""]    category_config = [        ("📌 新增招标采购意向", "采购意向公开"),        ("📢 新增招标公告", "招标公告"),        ("🏆 新增中标公告", "中标公告"),    ]    total = 0    for label, cat_key in category_config:        items = all_items.get(cat_key, [])        if not items:            continue        lines.append(f"{label} ({len(items)}条)")        lines.append("─" * 40)        for item in items:            title = item.get("title", "未知项目")            url = item.get("url", "")            budget = item.get("budget_amount") or item.get("budget", "")            pub_date = item.get("publish_date", "")            deadline = item.get("deadline", "")            purchaser = item.get("purchaser", "")            # 格式化预算            budget_str = ""            if budget:                try:                    budget_str = f"💰{float(budget):,.0f}元" if float(budget) > 100 else f"💰{float(budget):,.0f}万元"                except:                    budget_str = f"💰{budget}"            # 格式化时间            time_str = ""            if deadline:                time_str = f" | ⏰{deadline}"            elif pub_date:                time_str = f" | 🕐{pub_date}"            # 采购单位            dept_str = f" | 🏢{purchaser}" if purchaser else ""            # Feishu链接格式: [文本](url)            if url:                lines.append(f"• [{title}]({url}){budget_str}{time_str}{dept_str}")            else:                lines.append(f"• {title}{budget_str}{time_str}{dept_str}")            total += 1        lines.append("")    if total == 0:        lines.append("今日无新增招标采购信息")    else:        lines.append(f"📊 共 {total} 条 | 数据来源: 乐采云 (lecaiyun.com)")    return "\n".join(lines)# ── 状态管理 ──────────────────────────────────────────────def load_state() -> dict:    if STATE_FILE.exists():        try:            return json.loads(STATE_FILE.read_text(encoding="utf-8"))        except:            pass    return {"sent_items": [], "last_run": None}def save_state(state: dict, new_items: List[dict]):    # 用title+url作为去重key    for item in new_items:        key = f"{item.get('title','')}|{item.get('url','')}"        if key not in state["sent_items"]:            state["sent_items"].append(key)    state["sent_items"] = state["sent_items"][-2000:]  # 保留最近2000条    state["last_run"] = datetime.now().isoformat()    STATE_FILE.write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")def deduplicate(items: List[dict], state: dict) -> List[dict]:    sent = set(state.get("sent_items", []))    return [i for i in items if f"{i.get('title','')}|{i.get('url','')}" not in sent]# ── 主流程 ────────────────────────────────────────────────def main():    global today_str    # 支持命令行指定日期    if len(sys.argv) > 1:        today_str = sys.argv[1]    else:        today_str = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")    log.info("=" * 50)    log.info(f"开始抓取乐采云招标采购信息 - {today_str}")    # 1. 连接浏览器    try:        driver = get_driver()    except Exception:        log.error("无法连接Chrome，本次抓取取消")        print("LECAIYUN_ERROR: Chrome连接失败，请确保Chrome调试模式已启动")        return    all_items = {}    state = load_state()    try:        # 2. 抓取各类公告        for cat_name, url in SOURCE_URLS.items():            log.info(f"正在抓取: {cat_name}")            items = scrape_page(driver, url)            if items:                # 去重                new_items = deduplicate(items, state)                log.info(f"  {cat_name}: 总{len(items)}条, 新增{len(new_items)}条")                # 获取详情                if new_items:                    new_items = enrich_items(driver, new_items[:20])  # 限制详情抓取数量                all_items[cat_name] = new_items            else:                log.info(f"  {cat_name}: 无数据")                all_items[cat_name] = []            time.sleep(1)    finally:        driver.quit()    # 3. 去重检查（跨类别）    total_new = sum(len(v) for v in all_items.values())    if total_new == 0:        log.info("今日无新增乐采云招标采购信息")        print("NO_NEW_ITEMS")        return    # 4. 格式化简化报告    report = format_simplified_report(all_items)    # 5. 输出    print("REPORT_START")    print(report)    print("REPORT_END")    # 6. 保存JSON    json_file = SCRIPT_DIR / f"lecaiyun_data_{today_str}.json"    json_file.write_text(        json.dumps({            "date": today_str,            "items": all_items,        }, ensure_ascii=False, indent=2, default=str),        encoding="utf-8"    )    # 7. 更新状态    for cat_items in all_items.values():        save_state(state, cat_items)    log.info(f"完成! 共处理 {total_new} 条新增信息")    # 输出报告供飞书推送    print("\n-- 飞书推送用 --")    print(report)if __name__ == "__main__":    main()